<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {blankRule,chooseCompany,copy,validRule} from '../payrollUi'
import {storeToday} from '../time'
import type {PayrollHomeData,PayProfilePage,SalaryTemplate,CpfProfile,PrDocument,PaymentPreference} from '../payrollTypes'
import type {Option} from '../types'
import CdacProfileFields from '../components/CdacProfileFields.vue'
import type {CdacSetting} from '../cdac'
import PayRuleFields from '../components/PayRuleFields.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
const route=useRoute(),router=useRouter(),editing=!!route.params.id,id=String(route.params.id||crypto.randomUUID()),{api,r,t,base,current,loading,busy,failure,notice,load,write}=usePayrollPage(),company=ref(''),found=ref(false),savedCdac=ref(false),employees=ref<Option[]>([]),employeeBirthDates=ref<Record<string,string>>({}),employeePrDocuments=ref<Record<string,PrDocument[]>>({}),prConfirmed=ref(false),templates=ref<SalaryTemplate[]>([]),draft=reactive({expectedVersion:0,employeeId:'',effectiveFrom:storeToday(),templateId:'',rule:blankRule(),cpf:{citizenship:'citizen',birthDate:'',prDate:null,prMode:'GG',electionReference:''} as CpfProfile,payment:{method:'',bank:''} as {method:PaymentPreference['method']|'';bank:string},cdac:{status:'',reference:''} as {status:CdacSetting['status']|'';reference:string}})
const employeeBirthDate=computed(()=>employeeBirthDates.value[draft.employeeId]||'')
watch(()=>draft.employeeId,()=>{draft.cpf.birthDate=employeeBirthDate.value||'';if(found.value)clearPrReference()},{flush:'sync'})
watch(()=>draft.cpf.citizenship,()=>{if(found.value)clearPrReference()},{flush:'sync'})
const prDocuments=computed(()=>employeePrDocuments.value[draft.employeeId]||[]),selectedPrDocument=computed(()=>prDocuments.value.find(document=>document.id===draft.cpf.prDocumentId))
watch(()=>draft.cpf.prDocumentId,()=>{prConfirmed.value=false},{flush:'sync'})
function clearPrReference(){draft.cpf.prDate=null;draft.cpf.prDocumentId=null;prConfirmed.value=false}
function changePrSource(){prConfirmed.value=false;draft.cpf.prDate=selectedPrDocument.value?.prEffectiveOn||null}
function confirmPrSource(){if(prConfirmed.value&&selectedPrDocument.value)draft.cpf.prDate=selectedPrDocument.value.prEffectiveOn}
watch(()=>draft.cpf,()=>{if(employeeBirthDate.value)draft.cpf.birthDate=employeeBirthDate.value},{flush:'sync'})
function apply(){const s=templates.value.find(x=>x.id===draft.templateId);if(s)draft.rule=copy(s.rule)}
onMounted(()=>void load(async()=>{const h=await api().get<PayrollHomeData>('/payroll-home'),c=chooseCompany(h,String(route.query.companyId||''));const [data,ts]=await Promise.all([api().get<PayProfilePage>('/pay-profiles?companyId='+c),api().get<SalaryTemplate[]>('/salary-templates?companyId='+c)]);return {c,data,ts}},v=>{company.value=v.c;employees.value=v.data.employees;employeeBirthDates.value=v.data.employeeBirthDates||{};employeePrDocuments.value=v.data.employeePrDocuments||{};templates.value=v.ts;if(editing){const p=v.data.items.find(x=>x.id===id);if(!p){failure.value=t('notFound');return}savedCdac.value=!!p.cdac;Object.assign(draft,{expectedVersion:p.version,employeeId:p.employeeId,effectiveFrom:p.effectiveFrom,templateId:p.templateId,rule:copy(p.rule),payment:p.payment?copy(p.payment):{method:'',bank:''},cdac:p.cdac?copy(p.cdac):{status:'',reference:''},cpf:{...copy(p.cpf),prDocumentId:p.cpf.prDocumentId||null}})}else{draft.employeeId=employees.value[0]?.id||'';draft.templateId=templates.value.find(x=>x.enabled)?.id||'';apply()}found.value=true}))
function save(){const c=draft.cpf;if(!company.value||!found.value)return;if(c.citizenship==='spr'&&c.prDocumentId&&(!selectedPrDocument.value||!prConfirmed.value||c.prDate!==selectedPrDocument.value.prEffectiveOn)){failure.value=r(!selectedPrDocument.value?'prDocumentReview':'prDocumentRequired');return}if(!draft.employeeId||!draft.templateId||!draft.effectiveFrom||!validRule(draft.rule)||(draft.cdac.status==='applicable'&&c.citizenship==='foreign')||(['exempt','manual'].includes(draft.cdac.status)&&!draft.cdac.reference.trim())||(draft.cdac.status&&draft.cdac.status!=='manual'&&draft.rule.items.some(i=>i.kind==='cdac'))||(draft.payment.method==='bank'&&!draft.payment.bank.trim())||(c.citizenship!=='foreign'&&!c.birthDate)||(c.citizenship==='spr'&&(!c.prDate||c.prMode!=='GG'&&!c.electionReference.trim()))){failure.value=r('invalid');return}const cpf:CpfProfile={citizenship:c.citizenship,birthDate:c.birthDate||null,prDate:c.citizenship==='spr'?c.prDate:null,prMode:c.citizenship==='spr'?c.prMode:'GG',electionReference:c.citizenship==='spr'?c.electionReference.trim():'',prDocumentId:c.citizenship==='spr'?c.prDocumentId||null:null};void write(()=>api().put('/pay-profiles/'+id,{...draft,companyId:company.value,cpf,cdac:draft.cdac.status?{status:draft.cdac.status,reference:draft.cdac.reference.trim()}:null,payment:draft.payment.method?{method:draft.payment.method,bank:draft.payment.method==='cash'?'':draft.payment.bank.trim()}:null}),async()=>{if(current())await router.push({path:base.value+'/pay-profiles',query:{companyId:company.value}})})}
</script>
<template><section class="wf-panel wf-form-panel"><h2>{{r(editing?'editProfile':'newProfile')}}</h2><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><form v-if="found&&!loading" @submit.prevent="save"><fieldset :disabled="busy"><div class="wf-grid"><label>{{r('employee')}}<select v-model="draft.employeeId" :aria-label="r('employee')" required :disabled="editing"><option v-for="e in employees" :key="e.id" :value="e.id">{{e.name}}</option></select></label><label>{{r('effectiveFrom')}}<input v-model="draft.effectiveFrom" required type="date" :disabled="editing"></label></div><label>{{r('template')}}<select v-model="draft.templateId" required @change="apply"><option v-for="s in templates" :key="s.id" :value="s.id" :disabled="!s.enabled&&s.id!==draft.templateId">{{s.name}}</option></select></label><p class="wf-hint">{{r('templateHint')}}</p><PayRuleFields :rule="draft.rule" :disabled="busy"/><h2 class="wf-section">{{r('paymentPlan')}}</h2><div class="wf-grid"><label>{{r('method')}}<select v-model="draft.payment.method"><option value="">{{r('paymentUnknown')}}</option><option value="cash">{{r('cash')}}</option><option value="bank">{{r('bank')}}</option><option value="paynow">{{r('paynow')}}</option><option value="other">{{r('other')}}</option></select></label><label v-if="draft.payment.method&&draft.payment.method!=='cash'">{{r('bankName')}}<input v-model="draft.payment.bank" maxlength="100" :required="draft.payment.method==='bank'"></label></div><h2 class="wf-section">{{r('contributions')}}</h2><label>{{r('citizenship')}}<select v-model="draft.cpf.citizenship" :aria-label="r('citizenship')"><option value="citizen">{{r('citizen')}}</option><option value="spr">{{r('spr')}}</option><option value="foreign">{{r('foreign')}}</option></select></label><label>{{r('birthDate')}}<input v-model="draft.cpf.birthDate" type="date" :readonly="!!employeeBirthDate" :required="draft.cpf.citizenship!=='foreign'"></label><p v-if="employeeBirthDate" class="wf-hint">{{r('birthDateSource')}}</p><template v-if="draft.cpf.citizenship==='spr'"><label>{{r('prDateSource')}}<select v-model="draft.cpf.prDocumentId" :aria-label="r('prDateSource')" @change="changePrSource"><option :value="null">{{r('prManual')}}</option><option v-if="draft.cpf.prDocumentId&&!selectedPrDocument" :value="draft.cpf.prDocumentId" disabled>{{r('prDocumentMissing')}}</option><option v-for="document in prDocuments" :key="document.id" :value="document.id">{{document.typeName}} · {{document.number||document.holderName||document.id}} · {{document.prEffectiveOn}}</option></select></label><p class="wf-hint">{{r('prDocumentHint')}}</p><p v-if="draft.cpf.prDocumentId&&(!selectedPrDocument||draft.cpf.prDate!==selectedPrDocument.prEffectiveOn)" role="alert">{{r('prDocumentReview')}}</p><p v-if="selectedPrDocument" class="wf-hint">{{selectedPrDocument.holderName}} · {{r('prDocumentApproval')}}: {{selectedPrDocument.approvedOn||'—'}} · {{r('prDocumentDate')}}: {{selectedPrDocument.prEffectiveOn}}</p><label>{{r('prDate')}}<input v-model="draft.cpf.prDate" :aria-label="r('prDate')" :readonly="!!draft.cpf.prDocumentId" required type="date"></label><label v-if="selectedPrDocument" class="wf-inline"><input v-model="prConfirmed" :aria-label="r('prDocumentConfirm')" type="checkbox" @change="confirmPrSource">{{r('prDocumentConfirm')}}</label><label>{{r('prMode')}}<select v-model="draft.cpf.prMode"><option value="GG">{{r('GG')}}</option><option value="FG">{{r('FG')}}</option><option value="FF">{{r('FF')}}</option></select></label><label v-if="draft.cpf.prMode!=='GG'">{{r('electionReference')}}<textarea v-model="draft.cpf.electionReference" required maxlength="500" rows="2"></textarea></label></template><CdacProfileFields :configured="savedCdac" :setting="draft.cdac" :items="draft.rule.items" :citizenship="draft.cpf.citizenship"/></fieldset><p class="wf-hint">{{r('profileHint')}} {{r('supportHint')}}</p><footer class="wf-form-actions"><RouterLink class="wf-button" :to="{path:base+'/pay-profiles',query:{companyId:company}}">{{t('cancel')}}</RouterLink><button class="primary" :disabled="busy">{{busy?t('saving'):t('save')}}</button></footer></form></section></template>
